select jsonb_build_object('checked_at',clock_timestamp(),'expected',count(*),'exact',count(*)filter(where exact),'mismatches',coalesce(jsonb_agg(ref)filter(where not coalesce(exact,false)),'[]')) as verification from(select 'catalog_work_descriptions:33' as ref,(select to_jsonb(t) from public.catalog_work_descriptions t where t.work_id=987144008 and t.language='nl')='{"text":"In veertien verhalen onderzoekt Hanna Bervoets hoe mensen verbinding zoeken en hoe die verbinding kan haperen. Geliefden en vrienden proberen afstand en onbegrip te overbruggen, terwijl ook de verhouding tot dieren en de omringende wereld een rol speelt. De situaties lopen uiteen van herkenbare dagelijkse ontmoetingen tot raadselachtige omstandigheden. Steeds zoeken personages naar verhalen waarmee zij zichzelf en anderen kunnen begrijpen. De bundel laat zien hoe verlangen naar nabijheid soms juist tot vervreemding leidt.","work_id":987144008,"evidence":[{"note":"EenModernVerlangen2021 fourteenstories, exactDutchPaperback9789083142166. PrimaryPluimexactISBN/author andKBHannaMarleenBervoets boundtogether, notWatWijZagenor2022awarddate.","type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p433056789"],"reference":"new-work-dossier-readings-045.json#243","checked_at":"2026-11-03T09:13:56.273Z"},{"type":"original_substantive_source_review","review":"content-review-013.json","sources":["https://uitgeverijpluim.nl/boeken/een-modern-verlangen","https://uitgeverijpluim.nl/schrijvers/hanna-bervoets","https://www.nbdbiblion.nl/sites/nbdbiblion.nl/files/2021%20zomer%20TOTAAL.pdf","https://openlibrary.org/works/OL30303220W","https://data.bibliotheken.nl/id/nbt/p433056789"]},{"type":"explicit_contributor_roles","credits":[],"limitation":"Existing schema has one primary Work author; no synthetic combined-author identity or author merge."},{"note":"Exactsource-coverattempt retained; noverifiedasset imported. Inspect actualsameeditionresolver or documentedneutralplacehol